package com.shiphappens.logistics.config; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.slf4j.MDC; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.UUID;
@Component public class RequestIdFilter extends OncePerRequestFilter { @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException {String id=req.getHeader("X-Request-ID"); if(id==null||id.isBlank())id="REQ-"+UUID.randomUUID().toString().substring(0,8); req.setAttribute("requestId",id); res.setHeader("X-Request-ID",id); MDC.put("requestId",id); try{chain.doFilter(req,res);}finally{MDC.remove("requestId");}} }
